/** A wisp of steam rising at x, in an <svg> of its own, a column of the art's viewBox 40 units
 *  wide: WebKit moves an <svg> on its compositor, but an element inside one on its main thread,
 *  restyling the whole page with it every frame. */
function Wisp({
	x,
	d,
	className,
}: {
	x: number;
	d: string;
	className: string;
}) {
	return (
		<svg
			className={`steam ${className}`}
			viewBox={`${x - 20} -10 40 120`}
			style={vars({ "--x": `${x}` })}
			aria-hidden="true"
		>
			<path
				d={d}
				fill="none"
				stroke="var(--ink)"
				strokeWidth="5"
				strokeLinecap="round"
				opacity="0.13"
			/>
		</svg>
	);
}
